--
-- Table structure for table `wp_posts`
--

DROP TABLE IF EXISTS `wp_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wp_posts` (
  `ID` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_author` bigint(20) unsigned NOT NULL DEFAULT 0,
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(255) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint(20) unsigned NOT NULL DEFAULT 0,
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int(11) NOT NULL DEFAULT 0,
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint(20) NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`),
  KEY `post_name` (`post_name`(191)),
  KEY `type_status_date` (`post_type`,`post_status`,`post_date`,`ID`),
  KEY `post_parent` (`post_parent`),
  KEY `post_author` (`post_author`),
  KEY `type_status_author` (`post_type`,`post_status`,`post_author`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wp_posts`
--

LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2026-10-07 11:52:36','2026-10-07 11:52:36','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-10-07 11:52:36','2026-10-07 11:52:36','',0,'https://muopdangcungcovingot.io.vn/?p=1',0,'post','',1),(2,1,'2026-10-07 11:52:36','2026-10-07 11:52:36','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"https://muopdangcungcovingot.io.vn/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-10-07 11:52:36','2026-10-07 11:52:36','',0,'https://muopdangcungcovingot.io.vn/?page_id=2',0,'page','',0),(3,1,'2026-10-07 11:52:36','2026-10-07 11:52:36','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: https://muopdangcungcovingot.io.vn.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-10-07 11:52:36','2026-10-07 11:52:36','',0,'https://muopdangcungcovingot.io.vn/?page_id=3',0,'page','',0),(4,0,'2026-10-07 11:56:02','2026-10-07 11:56:02','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-10-07 11:56:02','2026-10-07 11:56:02','',0,'https://muopdangcungcovingot.io.vn/navigation/',0,'wp_navigation','',0),(5,0,'2026-10-07 12:06:54','2026-10-07 12:06:54','Trang Truy뿯ẽn M뿯ẽi C뿯ẽp Nh뿯ẽt','Truy뿯ẽn M뿯ẽi C뿯ẽp Nh뿯ẽt','','publish','closed','closed','','truyen-moi','','','2026-10-07 12:06:54','2026-10-07 12:06:54','',0,'https://muopdangcungcovingot.io.vn/truyen-moi/',0,'page','',0),(6,0,'2026-10-07 12:06:54','2026-10-07 12:06:54','Trang Truy뿯ẽn Hot','Truy뿯ẽn Hot','','publish','closed','closed','','truyen-hot','','','2026-10-07 12:06:54','2026-10-07 12:06:54','',0,'https://muopdangcungcovingot.io.vn/truyen-hot/',0,'page','',0),(7,0,'2026-10-07 12:06:54','2026-10-07 12:06:54','Trang Truy뿯ẽn Full','Truy뿯ẽn Full','','publish','closed','closed','','truyen-full','','','2026-10-07 12:06:54','2026-10-07 12:06:54','',0,'https://muopdangcungcovingot.io.vn/truyen-full/',0,'page','',0),(8,0,'2026-10-07 12:06:54','2026-10-07 12:06:54','Trang Th뿯ẽ Lo뿯ẽi Truy뿯ẽn','Th뿯ẽ Lo뿯ẽi Truy뿯ẽn','','publish','closed','closed','','the-loai','','','2026-10-07 12:06:54','2026-10-07 12:06:54','',0,'https://muopdangcungcovingot.io.vn/the-loai/',0,'page','',0),(9,0,'2026-10-07 12:06:54','2026-10-07 12:06:54','Trang Gi뿯ẽi Thi뿯ẽu','Gi뿯ẽi Thi뿯ẽu','','publish','closed','closed','','gioi-thieu','','','2026-10-07 12:06:54','2026-10-07 12:06:54','',0,'https://muopdangcungcovingot.io.vn/gioi-thieu/',0,'page','',0),(10,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang Đăng Nh뿯ẽp','Đăng Nh뿯ẽp','','publish','closed','closed','','dang-nhap','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/dang-nhap/',0,'page','',0),(11,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang Đăng K뿯½','Đăng K뿯½','','publish','closed','closed','','dang-ky','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/dang-ky/',0,'page','',0),(12,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang H뿯ẽ S뿯ƽ C뿯½ Nh뿯½n','H뿯ẽ S뿯ƽ C뿯½ Nh뿯½n','','publish','closed','closed','','ho-so','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/ho-so/',0,'page','',0),(13,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang Đăng Truy뿯ẽn M뿯ẽi','Đăng Truy뿯ẽn M뿯ẽi','','publish','closed','closed','','dang-truyen','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/dang-truyen/',0,'page','',0),(14,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang Th뿯½m Ch뿯ƽ뿯ƽng M뿯ẽi','Th뿯½m Ch뿯ƽ뿯ƽng M뿯ẽi','','publish','closed','closed','','them-chuong','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/them-chuong/',0,'page','',0),(15,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang K뿯½nh D뿯ẽch Gi뿯ẽ','K뿯½nh D뿯ẽch Gi뿯ẽ','','publish','closed','closed','','thong-tin-dich-gia','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/thong-tin-dich-gia/',0,'page','',0),(16,0,'2026-10-07 12:06:55','2026-10-07 12:06:55','Trang Qu뿯ẽn Tr뿯ẽ H뿯ẽ Th뿯ẽng','Qu뿯ẽn Tr뿯ẽ H뿯ẽ Th뿯ẽng','','publish','closed','closed','','quan-ly-admin','','','2026-10-07 12:06:55','2026-10-07 12:06:55','',0,'https://muopdangcungcovingot.io.vn/quan-ly-admin/',0,'page','',0),(17,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','Ba năm l뿯½m v뿯ẽ tr뿯½n danh nghĩa c뿯ẽa L뿯ẽc C뿯ẽnh Ho뿯½i, t뿯½i ngoan ngo뿯½n nghe l뿯ẽi, kh뿯½ng đ뿯½i h뿯ẽi m뿯ẽt danh ph뿯ẽn th뿯ẽc s뿯ẽ. Ng뿯½y c뿯½ g뿯½i thanh mai tr뿯½c m뿯½ c뿯ẽa anh tr뿯ẽ v뿯ẽ, t뿯½i ch뿯ẽ đ뿯ẽng đ뿯ƽa đ뿯ƽn ly h뿯½n k뿯½m m뿯ẽt ch뿯ẽ k뿯½ d뿯ẽt kho뿯½t.\n\nNh뿯ƽng ngay ng뿯½y h뿯½m sau, t뿯ẽi bu뿯ẽi ti뿯ẽc th뿯ƽ뿯ẽng l뿯ƽu, v뿯ẽ t뿯ẽng t뿯½i cao ng뿯ẽo n뿯ẽi ti뿯ẽng kh뿯ẽp kinh th뿯½nh l뿯ẽi n뿯ẽm ch뿯ẽt tay t뿯½i n뿯ƽi g뿯½c t뿯ẽi h뿯½nh lang, đ뿯½i m뿯ẽt đ뿯ẽ hoe: \'Em r뿯ẽi đi, ngay c뿯ẽ tr뿯½i tim t뿯½i em cũng mang theo r뿯ẽi sao?\'','M뿯ƽ뿯ẽp Đ뿯ẽng Cũng C뿯½ V뿯ẽ Ng뿯ẽt: Sau Ly H뿯½n T뿯½i Tr뿯ẽ Th뿯½nh 뿯½nh Trăng S뿯½ng C뿯ẽa T뿯ẽng T뿯½i','','publish','open','closed','','muop-dang-cung-co-vi-ngot-sau-ly-hon-toi-tro-thanh-anh-trang-sang-cua-tong-tai','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/truyen/muop-dang-cung-co-vi-ngot-sau-ly-hon-toi-tro-thanh-anh-trang-sang-cua-tong-tai/',0,'truyen','',1),(18,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>Tr뿯ẽi m뿯ƽa r뿯ẽ r뿯½ch su뿯ẽt ba ng뿯½y 뿯ẽ Kinh Đ뿯½.</p><p>H뿯ẽa Nh뿯ƽ뿯ẽc Ng뿯ƽng đ뿯ẽt t뿯½ch tr뿯½ l뿯½i 뿯ẽm n뿯½ng l뿯½n b뿯½n tr뿯½, ng뿯½n tay nh뿯ẽ nh뿯½ng đ뿯ẽy t뿯ẽ gi뿯ẽy th뿯ẽa thu뿯ẽn ly h뿯½n đ뿯½ k뿯½ s뿯ẽn t뿯½n m뿯½nh sang ph뿯½a ng뿯ƽ뿯ẽi đ뿯½n 뿯½ng ng뿯ẽi đ뿯ẽi di뿯ẽn.</p><p>\'L뿯ẽc C뿯ẽnh Ho뿯½i, ch뿯½ng ta d뿯ẽng l뿯ẽi 뿯ẽ đ뿯½y th뿯½i. Ba năm qua, c뿯ẽm 뿯ƽn anh đ뿯½ chăm s뿯½c.\'</p><p>Ng뿯ƽ뿯ẽi đ뿯½n 뿯½ng m뿯ẽc 뿯½u ph뿯ẽc may đo m뿯½u x뿯½m tro h뿯ƽi kh뿯ẽng l뿯ẽi. Anh ng뿯ẽng đ뿯ẽu l뿯½n t뿯ẽ t뿯ẽp t뿯½i li뿯ẽu t뿯½i ch뿯½nh, 뿯½nh m뿯ẽt th뿯½m tr뿯ẽm nh뿯ƽ đ뿯½y h뿯ẽ kh뿯½ng m뿯ẽt g뿯ẽn s뿯½ng: \'Em ch뿯ẽc ch뿯ẽn? Em bi뿯ẽt r뿯½ r뿯ẽi kh뿯ẽi L뿯ẽc gia, em s뿯ẽ kh뿯½ng c뿯½ đ뿯ƽ뿯ẽc b뿯ẽt c뿯ẽ th뿯ẽ g뿯½ ngo뿯½i s뿯ẽ ti뿯ẽn b뿯ẽi th뿯ƽ뿯ẽng.\'</p><p>\'T뿯½i ch뿯ẽc ch뿯ẽn.\' Nh뿯ƽ뿯ẽc Ng뿯ƽng m뿯ẽm c뿯ƽ뿯ẽi nh뿯ẽ nh뿯½m, n뿯ẽ c뿯ƽ뿯ẽi m뿯½ ba năm qua anh ch뿯ƽa t뿯ẽng th뿯ẽy tr뿯½n g뿯ƽ뿯ƽng m뿯ẽt c뿯½.</p>','Ch뿯ƽ뿯ƽng 1: Quy뿯ẽt đ뿯ẽnh k뿯½ đ뿯ƽn ly h뿯½n','','publish','open','closed','','chuong-1-quyet-dinh-ky-don-ly-hon','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-1-quyet-dinh-ky-don-ly-hon/',0,'chuong','',0),(19,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>Hai th뿯½ng sau khi r뿯ẽi kh뿯ẽi L뿯ẽc gia.</p><p>Kh뿯½ch s뿯ẽn Đ뿯ẽ Đ뿯½ l뿯ẽng l뿯ẽy 뿯½nh đ뿯½n pha l뿯½. H뿯½m nay l뿯½ bu뿯ẽi ti뿯ẽc th뿯ẽi trang l뿯ẽn nh뿯ẽt năm c뿯ẽa t뿯ẽp đo뿯½n V뿯ẽn Tinh. Nh뿯ƽ뿯ẽc Ng뿯ƽng xu뿯ẽt hi뿯ẽn trong chi뿯ẽc đ뿯ẽm d뿯ẽ h뿯ẽi satin m뿯½u xanh b뿯ƽ 뿯½m tr뿯ẽn đ뿯ƽ뿯ẽng cong m뿯ẽm m뿯ẽi, m뿯½i t뿯½c u뿯ẽn s뿯½ng bu뿯½ng l뿯ƽi quy뿯ẽn rũ.</p><p>Khi c뿯½ b뿯ƽ뿯ẽc l뿯½n b뿯ẽc nh뿯ẽn gi뿯ẽi Nh뿯½ thi뿯ẽt k뿯ẽ c뿯ẽa năm, to뿯½n b뿯ẽ quan kh뿯½ch d뿯ƽ뿯ẽi kh뿯½n đ뿯½i đ뿯ẽu s뿯ẽng s뿯ẽ. Đ뿯ẽc bi뿯ẽt l뿯½ L뿯ẽc C뿯ẽnh Ho뿯½i 뿯ẽ h뿯½ng gh뿯ẽ VIP.</p><p>Ly r뿯ƽ뿯ẽu vang tr뿯½n tay anh su뿯½t ch뿯½t n뿯ẽa r뿯ƽi xu뿯ẽng th뿯ẽm. C뿯½ g뿯½i nh뿯ẽ lu뿯½n e th뿯ẽn 뿯ẽ nh뿯½ n뿯ẽu canh cho anh m뿯ẽi t뿯ẽi, h뿯½a ra l뿯ẽi l뿯½ nh뿯½ thi뿯ẽt k뿯ẽ 뿯ẽn danh huy뿯ẽn tho뿯ẽi m뿯½ gi뿯ẽi th뿯ẽi trang qu뿯ẽc t뿯ẽ săn đ뿯½n b뿯ẽy l뿯½u!</p>','Ch뿯ƽ뿯ƽng 2: M뿯½n g뿯ẽp l뿯ẽi b뿯ẽt ng뿯ẽ t뿯ẽi y뿯ẽn ti뿯ẽc','','publish','open','closed','','chuong-2-man-gap-lai-bat-ngo-tai-yen-tiec','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-2-man-gap-lai-bat-ngo-tai-yen-tiec/',0,'chuong','',0),(20,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>\'Em tr뿯½nh m뿯ẽt t뿯½i?\' Gi뿯ẽng n뿯½i tr뿯ẽm kh뿯½n quen thu뿯ẽc vang l뿯½n sau l뿯ƽng khi Nh뿯ƽ뿯ẽc Ng뿯ƽng v뿯ẽa b뿯ƽ뿯ẽc ra h뿯½nh lang đ뿯½n gi뿯½.</p><p>C뿯½ ch뿯ƽa k뿯ẽp quay l뿯ẽi th뿯½ m뿯ẽt c뿯½nh tay r뿯ẽn r뿯ẽi đ뿯½ 뿯½p s뿯½t th뿯½nh t뿯ƽ뿯ẽng, ch뿯ẽn đ뿯ẽng l뿯ẽi đi c뿯ẽa c뿯½. M뿯½i h뿯ƽ뿯ƽng g뿯ẽ tuy뿯ẽt t뿯½ng quen thu뿯ẽc bao tr뿯½m l뿯ẽy kh뿯½ng gian.</p><p>\'L뿯ẽc t뿯ẽng, 뿯ẽ đ뿯½y c뿯½ r뿯ẽt nhi뿯ẽu ph뿯½ng vi뿯½n, xin t뿯ẽ tr뿯ẽng.\' C뿯½ b뿯½nh tĩnh ng뿯ƽ뿯ẽc nh뿯½n anh.</p><p>L뿯ẽc C뿯ẽnh Ho뿯½i c뿯½i th뿯ẽp đ뿯ẽu, h뿯ƽi th뿯ẽ ph뿯ẽ qua v뿯½nh tai m뿯ẽn c뿯ẽm c뿯ẽa c뿯½: \'T뿯ẽ tr뿯ẽng? Nh뿯ƽ뿯ẽc Ng뿯ƽng, hai th뿯½ng qua t뿯½i ch뿯ƽa t뿯ẽng ng뿯ẽ tr뿯ẽn m뿯ẽt đ뿯½m n뿯½o. Em n뿯½i xem, em đ뿯½ b뿯ẽ b뿯½a g뿯½ v뿯½o căn nh뿯½ c뿯ẽa t뿯½i?\'</p>','Ch뿯ƽ뿯ƽng 3: G뿯½c t뿯ẽi h뿯½nh lang v뿯½ l뿯ẽi th뿯ẽm th뿯½','','publish','open','closed','','chuong-3-goc-toi-hanh-lang-va-loi-tham-thi','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-3-goc-toi-hanh-lang-va-loi-tham-thi/',0,'chuong','',0),(21,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>Nh뿯ƽ뿯ẽc Ng뿯ƽng đ뿯ẽy nh뿯ẽ ng뿯ẽc 뿯½o c뿯ẽa anh ra: \'L뿯ẽc t뿯ẽng đ뿯½a sao? B뿯ẽch nguy뿯ẽt quang c뿯ẽa anh đ뿯½ v뿯ẽ n뿯ƽ뿯ẽc r뿯ẽi, anh n뿯½n d뿯½nh s뿯ẽ quan t뿯½m n뿯½y cho c뿯½ 뿯ẽy m뿯ẽi ph뿯ẽi.\'</p><p>L뿯ẽc C뿯ẽnh Ho뿯½i b뿯ẽt c뿯ƽ뿯ẽi cay đ뿯ẽng: \'B뿯ẽch nguy뿯ẽt quang n뿯½o ch뿯ẽ? Ng뿯ƽ뿯ẽi t뿯½i lu뿯½n t뿯½m ki뿯ẽm t뿯ẽ 10 năm tr뿯ƽ뿯ẽc 뿯ẽ tr뿯ẽi h뿯½ năm đ뿯½... ch뿯½nh l뿯½ ng뿯ƽ뿯ẽi đang đ뿯ẽng tr뿯ƽ뿯ẽc m뿯ẽt t뿯½i b뿯½y gi뿯ẽ.\'</p><p>Đ뿯½i m뿯ẽt Nh뿯ƽ뿯ẽc Ng뿯ƽng kh뿯ẽ ch뿯ẽp đ뿯ẽng. K뿯½ 뿯ẽc v뿯ẽ m뿯½a h뿯½ năm 뿯ẽy đ뿯ẽt ng뿯ẽt 뿯½a v뿯ẽ...</p>','Ch뿯ƽ뿯ƽng 4: Tr뿯½i tim b뿯ẽt đ뿯ẽu tan ch뿯ẽy','','publish','open','closed','','chuong-4-trai-tim-bat-dau-tan-chay','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-4-trai-tim-bat-dau-tan-chay/',0,'chuong','',0),(22,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>M뿯ƽa l뿯ẽi b뿯ẽt đ뿯ẽu r뿯ƽi ngo뿯½i ban c뿯½ng.</p><p>L뿯ẽc C뿯ẽnh Ho뿯½i n뿯ẽm l뿯ẽy b뿯½n tay m뿯ẽnh kh뿯ẽnh c뿯ẽa Nh뿯ƽ뿯ẽc Ng뿯ƽng, 뿯½p l뿯½n l뿯ẽng ng뿯ẽc đang đ뿯ẽp li뿯½n h뿯ẽi c뿯ẽa m뿯½nh: \'N뿯ẽu tr뿯ƽ뿯ẽc đ뿯½y t뿯½i khi뿯ẽn em c뿯ẽm th뿯ẽy nh뿯ƽ m뿯ẽt tr뿯½i m뿯ƽ뿯ẽp đ뿯ẽng ch뿯½t, th뿯½ t뿯ẽ h뿯½m nay, t뿯½i s뿯ẽ ch뿯ẽng minh cho em th뿯ẽy... m뿯ƽ뿯ẽp đ뿯ẽng c뿯ẽa em c뿯½ v뿯ẽ ng뿯ẽt l뿯ẽm nh뿯ƽ th뿯ẽ n뿯½o.\'</p><p>C뿯½ nh뿯½n v뿯½o 뿯½nh m뿯ẽt ch뿯½n th뿯½nh ch뿯ƽa t뿯ẽng c뿯½ c뿯ẽa anh, b뿯ẽ m뿯½i kh뿯ẽ cong l뿯½n m뿯ẽt n뿯ẽ c뿯ƽ뿯ẽi 뿯ẽm 뿯½p.</p>','Ch뿯ƽ뿯ƽng 5: L뿯ẽi th뿯ẽ ng뿯ẽt ng뿯½o d뿯ƽ뿯ẽi m뿯ƽa','','publish','open','closed','','chuong-5-loi-the-ngot-ngao-duoi-mua','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-5-loi-the-ngot-ngao-duoi-mua/',0,'chuong','',0),(23,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','Ki뿯ẽp tr뿯ƽ뿯ẽc, t뿯½i v뿯½ c뿯ẽu v뿯ẽ h뿯½n phu v뿯½ c뿯½ em g뿯½i nu뿯½i m뿯½ b뿯ẽ h뿯ẽy ho뿯ẽi dung nhan, cu뿯ẽi c뿯½ng b뿯ẽ b뿯ẽn h뿯ẽ đ뿯ẽy xu뿯ẽng bi뿯ẽn l뿯ẽnh gi뿯½ v뿯½o đ뿯½m đ뿯½ng. M뿯ẽ m뿯ẽt ra l뿯ẽn n뿯ẽa, t뿯½i đ뿯½ quay tr뿯ẽ l뿯ẽi năm 18 tu뿯ẽi, đ뿯½ng ng뿯½y b뿯ẽn h뿯ẽ b뿯½y m뿯ƽu l뿯ẽa t뿯½i v뿯½o căn ph뿯½ng ch뿯½y...','Tr뿯ẽng Sinh V뿯ẽ Năm 18 Tu뿯ẽi: T뿯½i Kh뿯½ng L뿯½m K뿯ẽ Ng뿯ẽc N뿯ẽa','','publish','open','closed','','trong-sinh-ve-nam-18-tuoi-toi-khong-lam-ke-ngoc-nua','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/truyen/trong-sinh-ve-nam-18-tuoi-toi-khong-lam-ke-ngoc-nua/',0,'truyen','',1),(24,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>C뿯ẽm gi뿯½c n뿯ƽ뿯ẽc bi뿯ẽn l뿯ẽnh bu뿯ẽt tr뿯½n v뿯½o ph뿯ẽi tan bi뿯ẽn trong t뿯½ch t뿯ẽc.</p><p>T뿯½i b뿯ẽng t뿯ẽnh, đ뿯ẽp v뿯½o m뿯ẽt l뿯½ tr뿯ẽn nh뿯½ m뿯½u xanh nh뿯ẽt quen thu뿯ẽc c뿯ẽa căn ph뿯½ng ng뿯ẽ năm 18 tu뿯ẽi. Tr뿯½n b뿯½n h뿯ẽc, cu뿯ẽn l뿯ẽch b뿯½n ghi r뿯½ ng뿯½y 15 th뿯½ng 5 năm 2018.</p><p>\'M뿯½nh... th뿯ẽt s뿯ẽ đ뿯½ tr뿯ẽng sinh r뿯ẽi sao?\' T뿯½i s뿯ẽ l뿯½n g뿯ƽ뿯ƽng m뿯ẽt m뿯ẽn m뿯½ng kh뿯½ng t뿯½ v뿯ẽt c뿯ẽa m뿯½nh, n뿯ƽ뿯ẽc m뿯ẽt tu뿯½n r뿯ƽi nh뿯ƽng mi뿯ẽng l뿯ẽi m뿯ẽm c뿯ƽ뿯ẽi s뿯ẽc l뿯ẽnh.</p>','Ch뿯ƽ뿯ƽng 1: T뿯ẽnh l뿯ẽi trong c뿯ƽn 뿯½c m뿯ẽng','','publish','open','closed','','chuong-1-tinh-lai-trong-con-ac-mong','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-1-tinh-lai-trong-con-ac-mong/',0,'chuong','',0),(25,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>Bu뿯ẽi chi뿯ẽu h뿯½m 뿯ẽy, đi뿯ẽn tho뿯ẽi t뿯½i rung l뿯½n th뿯½ng b뿯½o tin nh뿯ẽn t뿯ẽ C뿯ẽ Gia Th뿯½nh: \'Nhi뿯½n Nhi뿯½n, em t뿯ẽi kho th뿯ẽ d뿯ẽc t뿯ẽng 3 gi뿯½p anh l뿯ẽy h뿯ẽ s뿯ƽ nh뿯½, anh đang b뿯ẽn h뿯ẽp.\'</p><p>Tin nh뿯ẽn y h뿯ẽt nh뿯ƽ ki뿯ẽp tr뿯ƽ뿯ẽc. L뿯ẽn đ뿯½, t뿯½i ch뿯ẽy t뿯ẽi v뿯½ b뿯ẽ nh뿯ẽt trong đ뿯½m ch뿯½y, c뿯½n anh ta v뿯½ em g뿯½i nu뿯½i L뿯½m Vi Vi l뿯ẽi c뿯½ng nhau ăn kem 뿯ẽ qu뿯½n c뿯½ ph뿯½ đ뿯ẽi di뿯ẽn.</p><p>T뿯½i kh뿯ẽ nh뿯ẽch m뿯½i, b뿯ẽm chuy뿯ẽn ti뿯ẽp tin nh뿯ẽn 뿯ẽy cho ch뿯½nh L뿯½m Vi Vi k뿯½m l뿯ẽi nh뿯ẽn: \'Ch뿯ẽ b뿯ẽn r뿯ẽi, em t뿯ẽi gi뿯½p anh Gia Th뿯½nh nh뿯½!\'</p>','Ch뿯ƽ뿯ƽng 2: K뿯ẽ ho뿯ẽch ph뿯ẽn đ뿯½n ho뿯½n h뿯ẽo','','publish','open','closed','','chuong-2-ke-hoach-phan-don-hoan-hao','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-2-ke-hoach-phan-don-hoan-hao/',0,'chuong','',0),(26,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>Khi ti뿯ẽng c뿯½i xe c뿯ẽu h뿯ẽa r뿯½ vang kh뿯ẽp s뿯½n tr뿯ƽ뿯ẽng, t뿯½i đ뿯ẽng t뿯ẽ ban c뿯½ng t뿯ẽng 5 nh뿯½n xu뿯ẽng.</p><p>L뿯½m Vi Vi ho s뿯ẽc s뿯ẽa đ뿯ƽ뿯ẽc l뿯½nh c뿯ẽu h뿯ẽa đ뿯ƽa ra ngo뿯½i, chi뿯ẽc v뿯½y hi뿯ẽu đ뿯ẽt ti뿯ẽn l뿯ẽm lem b뿯½n đ뿯ẽt tro t뿯½n. C뿯ẽ Gia Th뿯½nh h뿯ẽt h뿯ẽi ch뿯ẽy t뿯ẽi, nh뿯½n th뿯ẽy t뿯½i đ뿯ẽng l뿯½nh l뿯ẽn xinh đ뿯ẽp b뿯½n c뿯ẽnh th뿯½ s뿯ẽc m뿯ẽt t뿯½i nh뿯ẽt nh뿯ƽ x뿯½c 뿯ƽ뿯ẽp.</p><p>\'Ch뿯½o C뿯ẽ thi뿯ẽu, tr뿯½ ch뿯ƽi b뿯½y gi뿯ẽ m뿯ẽi ch뿯ẽ b뿯ẽt đ뿯ẽu th뿯½i!\'</p>','Ch뿯ƽ뿯ƽng 3: K뿯ẽ gieo gi뿯½ g뿯ẽt b뿯½o','','publish','open','closed','','chuong-3-ke-gieo-gio-gat-bao','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-3-ke-gieo-gio-gat-bao/',0,'chuong','',0),(27,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','V뿯½ l뿯½m v뿯ẽa l뿯½ng ng뿯ƽ뿯ẽi l뿯ẽn hai b뿯½n, t뿯½i k뿯ẽt h뿯½n ch뿯ẽp nho뿯½ng v뿯ẽi v뿯ẽ gi뿯½o s뿯ƽ v뿯ẽt l뿯½ tr뿯ẽ tu뿯ẽi nh뿯ẽt vi뿯ẽn h뿯½n l뿯½m. Ban ng뿯½y tr뿯½n gi뿯ẽng đ뿯ƽ뿯ẽng anh l뿯ẽnh l뿯½ng nghi뿯½m ngh뿯ẽ bao nhi뿯½u, th뿯½ đ뿯½m v뿯ẽ l뿯ẽi 뿯½m ch뿯ẽt l뿯ẽy t뿯½i d뿯ẽ d뿯½nh b뿯ẽy nhi뿯½u...','C뿯ƽ뿯ẽi Tr뿯ƽ뿯ẽc Y뿯½u Sau: Gi뿯½o S뿯ƽ Nghi뿯½m T뿯½c Ban Ng뿯½y Ban Đ뿯½m L뿯ẽi R뿯ẽt Qu뿯ẽn Ng뿯ƽ뿯ẽi','','publish','open','closed','','cuoi-truoc-yeu-sau-giao-su-nghiem-tuc-ban-ngay-ban-dem-lai-rat-quan-nguoi','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/truyen/cuoi-truoc-yeu-sau-giao-su-nghiem-tuc-ban-ngay-ban-dem-lai-rat-quan-nguoi/',0,'truyen','',1),(28,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>Gi뿯½o s뿯ƽ C뿯ẽ Th뿯ẽn ng뿯ẽi đ뿯ẽi di뿯ẽn t뿯½i trong qu뿯½n c뿯½ ph뿯½ s뿯½ch, 뿯½o s뿯ƽ mi tr뿯ẽng ph뿯ẽng phiu c뿯½i c뿯½c t뿯ẽn c뿯ẽ.</p><p>\'M뿯ẽc đ뿯½ch xem m뿯ẽt c뿯ẽa t뿯½i l뿯½ k뿯ẽt h뿯½n đ뿯ẽ 뿯ẽn đ뿯ẽnh gia đ뿯½nh. N뿯ẽu c뿯½ Chu kh뿯½ng ph뿯ẽn đ뿯ẽi, tu뿯ẽn sau ch뿯½ng ta c뿯½ th뿯ẽ đăng k뿯½.\'</p><p>T뿯½i ng뿯ƽ ng뿯½c nh뿯½n anh: \'Nhanh v뿯ẽy sao gi뿯½o s뿯ƽ C뿯ẽ?\'</p><p>\'Hi뿯ẽu qu뿯ẽ l뿯½ ti뿯½u chu뿯ẽn s뿯ẽ m뿯ẽt trong m뿯ẽi th뿯½ nghi뿯ẽm v뿯ẽt l뿯½ c뿯ẽa t뿯½i.\' Anh tr뿯ẽ l뿯ẽi t뿯ẽnh queo.</p>','Ch뿯ƽ뿯ƽng 1: Cu뿯ẽc xem m뿯ẽt đ뿯ẽnh m뿯ẽnh','','publish','open','closed','','chuong-1-cuoc-xem-mat-dinh-menh','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-1-cuoc-xem-mat-dinh-menh/',0,'chuong','',0),(29,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>T뿯½i 뿯½m g뿯ẽi đ뿯ẽnh ra s뿯½-pha ng뿯ẽ đ뿯ẽ gi뿯ẽ kho뿯ẽng c뿯½ch, nh뿯ƽng ch뿯ƽa k뿯ẽp b뿯ƽ뿯ẽc ch뿯½n th뿯½ c뿯½nh c뿯ẽa ph뿯½ng ng뿯ẽ đ뿯½ b뿯ẽ kh뿯½a tr뿯½i.</p><p>Gi뿯½o s뿯ƽ C뿯ẽ th뿯½o m뿯ẽt k뿯½nh g뿯ẽng v뿯½ng, 뿯½nh m뿯ẽt kh뿯½ng c뿯½n v뿯ẽ nghi뿯½m c뿯ẽn th뿯ƽ뿯ẽng ng뿯½y: \'Chu phu nh뿯½n, theo lu뿯ẽt h뿯½n nh뿯½n v뿯½ quy t뿯ẽc x뿯½c su뿯ẽt, ch뿯½ng ta n뿯½n ng뿯ẽ chung gi뿯ƽ뿯ẽng.\'</p>','Ch뿯ƽ뿯ƽng 2: Đ뿯½m t뿯½n h뿯½n b뿯ẽt ng뿯ẽ','','publish','open','closed','','chuong-2-dem-tan-hon-bat-ngo','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-2-dem-tan-hon-bat-ngo/',0,'chuong','',0),(30,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','Xuy뿯½n v뿯½o cu뿯ẽn ti뿯ẽu thuy뿯ẽt c뿯ẽu huy뿯ẽt, t뿯½i th뿯½nh v뿯ẽ h뿯½n th뿯½ đ뿯ẽc 뿯½c chuy뿯½n c뿯ẽn tr뿯ẽ nam n뿯ẽ ch뿯½nh. Thay v뿯½ đ뿯ẽu đ뿯½ đ뿯ẽ b뿯ẽ ch뿯½m đ뿯ẽu, t뿯½i quy뿯ẽt đ뿯ẽnh lui v뿯ẽ th뿯½n qu뿯½ đ뿯½o ao nu뿯½i c뿯½, tr뿯ẽng d뿯ƽa h뿯ẽu. N뿯½o ng뿯ẽ nam ch뿯½nh l뿯ẽi t뿯ẽ b뿯ẽ kinh th뿯½nh đ뿯ẽ v뿯ẽ l뿯½m n뿯½ng d뿯½n c뿯½ng t뿯½i...','Xuy뿯½n S뿯½ch Th뿯½nh N뿯ẽ Ph뿯ẽ Ph뿯½o H뿯½i: T뿯½i Quy뿯ẽt Đ뿯ẽnh N뿯ẽm Y뿯½n Nu뿯½i C뿯½','','publish','open','closed','','xuyen-sach-thanh-nu-phu-phao-hoi-toi-quyet-dinh-nam-yen-nuoi-ca','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/truyen/xuyen-sach-thanh-nu-phu-phao-hoi-toi-quyet-dinh-nam-yen-nuoi-ca/',0,'truyen','',1),(31,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>V뿯ẽa m뿯ẽ m뿯ẽt ra, m뿯ẽt nha ho뿯½n đ뿯½ kh뿯½c l뿯½c: \'Ti뿯ẽu th뿯ƽ, V뿯ƽ뿯ƽng gia s뿯ẽp h뿯ẽy h뿯½n r뿯ẽi, ng뿯ƽ뿯ẽi đ뿯ẽng nh뿯ẽy gi뿯ẽng n뿯ẽa!\'</p><p>T뿯½i ng뿯ẽi d뿯ẽy, ph뿯ẽi b뿯ẽi tr뿯½n v뿯½y: \'H뿯ẽy h뿯½n th뿯ẽt 뿯½? Th뿯ẽ c뿯ẽa h뿯ẽi m뿯½n c뿯½ tr뿯ẽ l뿯ẽi đ뿯ẽ kh뿯½ng?\'</p><p>Nha ho뿯½n ng뿯ẽn ng뿯ƽ g뿯ẽt đ뿯ẽu: \'D뿯ẽ tr뿯ẽ đ뿯ẽ...\'</p><p>\'T뿯ẽt l뿯ẽm! Thu d뿯ẽn h뿯½nh l뿯½, ch뿯½ng ta v뿯ẽ qu뿯½ mua đ뿯ẽt x뿯½y trang tr뿯ẽi!\'</p>','Ch뿯ƽ뿯ƽng 1: T뿯ẽnh d뿯ẽy 뿯ẽ h뿯ẽu vi뿯ẽn','','publish','open','closed','','chuong-1-tinh-day-o-hau-vien','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-1-tinh-day-o-hau-vien/',0,'chuong','',0),(32,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>N뿯ẽa năm sau, trang tr뿯ẽi nu뿯½i c뿯½ c뿯ẽa t뿯½i n뿯ẽc ti뿯ẽng c뿯ẽ v뿯½ng.</p><p>M뿯ẽt h뿯½m, m뿯ẽt thi뿯ẽu ni뿯½n tu뿯ẽn t뿯½ tu뿯ẽn m뿯½ xu뿯ẽt hi뿯ẽn tr뿯ƽ뿯ẽc c뿯ẽng tre, qu뿯ẽ m뿯ẽt g뿯ẽi tr뿯ƽ뿯ẽc đ뿯ẽm sen: \'N뿯½ng cho ta l뿯½m c뿯½ng nh뿯½n chăm c뿯½ đ뿯ƽ뿯ẽc kh뿯½ng? Kh뿯½ng c뿯ẽn l뿯ƽ뿯ƽng, ch뿯ẽ c뿯ẽn m뿯ẽt ch뿯½n c뿯ƽm v뿯½ m뿯ẽt n뿯ẽ c뿯ƽ뿯ẽi c뿯ẽa n뿯½ng m뿯ẽi ng뿯½y.\'</p>','Ch뿯ƽ뿯ƽng 2: V뿯ƽ뿯ƽng gia t뿯ẽi l뿯½m t뿯½ đi뿯ẽn','','publish','open','closed','','chuong-2-vuong-gia-toi-lam-ta-dien','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-2-vuong-gia-toi-lam-ta-dien/',0,'chuong','',0),(33,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','T뿯½i l뿯½ đ뿯ẽa con g뿯½i ru뿯ẽt b뿯ẽ th뿯ẽt l뿯ẽc 15 năm, nh뿯ƽng khi tr뿯ẽ v뿯ẽ ch뿯ẽ nh뿯ẽn l뿯ẽi s뿯ẽ gh뿯ẽ l뿯ẽnh t뿯ẽ b뿯ẽ m뿯ẽ v뿯½ ba ng뿯ƽ뿯ẽi anh trai. H뿯ẽ c뿯ƽng chi뿯ẽu con g뿯½i nu뿯½i, 뿯½p t뿯½i hi뿯ẽn t뿯ẽy r뿯ẽi đu뿯ẽi t뿯½i ra kh뿯ẽi nh뿯½ gi뿯ẽa đ뿯½m đ뿯½ng. Ng뿯½y t뿯½i qua đ뿯ẽi v뿯½ b뿯ẽo b뿯ẽnh, cu뿯ẽn nh뿯ẽt k뿯½ c뿯ẽa t뿯½i đ뿯ƽ뿯ẽc c뿯½ng khai...','Sau Khi T뿯½i Ch뿯ẽt, To뿯½n Th뿯ẽ Nh뿯½ H뿯ẽ Th뿯ẽm H뿯ẽi H뿯ẽn Kh뿯½ng K뿯ẽp','','publish','open','closed','','sau-khi-toi-chet-toan-the-nha-ho-tham-hoi-han-khong-kip','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/truyen/sau-khi-toi-chet-toan-the-nha-ho-tham-hoi-han-khong-kip/',0,'truyen','',1),(34,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>\'B뿯ẽ m뿯ẽ, c뿯½c anh... n뿯ẽu m뿯ẽi ng뿯ƽ뿯ẽi đ뿯ẽc đ뿯ƽ뿯ẽc nh뿯ẽng d뿯½ng n뿯½y, c뿯½ l뿯ẽ tro c뿯ẽt c뿯ẽa con đ뿯½ đ뿯ƽ뿯ẽc r뿯ẽi ngo뿯½i bi뿯ẽn kh뿯ƽi r뿯ẽi.\'</p><p>T뿯ẽi tang l뿯ẽ hoang t뿯½n kh뿯½ng m뿯ẽt v뿯½ng hoa, ng뿯ƽ뿯ẽi anh c뿯ẽ run r뿯ẽy c뿯ẽm cu뿯ẽn s뿯ẽ tay d뿯½nh m뿯½u m뿯ẽ t뿯ẽng trang. Nh뿯ẽng b뿯½ m뿯ẽt v뿯ẽ ng뿯ƽ뿯ẽi em g뿯½i ru뿯ẽt lu뿯½n c뿯ẽn răng ch뿯ẽu đ뿯ẽng v뿯½ y뿯½u th뿯ƽ뿯ƽng gia đ뿯½nh d뿯ẽn h뿯½ l뿯ẽ...</p>','Ch뿯ƽ뿯ƽng 1: L뿯½ th뿯ƽ cu뿯ẽi c뿯½ng','','publish','open','closed','','chuong-1-la-thu-cuoi-cung','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-1-la-thu-cuoi-cung/',0,'chuong','',0),(35,2,'2026-10-07 12:08:40','2026-10-07 12:08:40','<p>B뿯½ Th뿯ẽm ng뿯½ qu뿯ẽ tr뿯ƽ뿯ẽc di 뿯ẽnh c뿯ẽa con g뿯½i ru뿯ẽt, g뿯½o kh뿯½c th뿯ẽm thi뿯ẽt: \'M뿯ẽ sai r뿯ẽi... Uy뿯ẽn Uy뿯ẽn 뿯ƽi, con v뿯ẽ v뿯ẽi m뿯ẽ đi!\'</p><p>Nh뿯ƽng đ뿯½p l뿯ẽi ch뿯ẽ l뿯½ ti뿯ẽng gi뿯½ r뿯½t qua 뿯½ c뿯ẽa s뿯ẽ l뿯ẽnh bu뿯ẽt...</p>','Ch뿯ƽ뿯ƽng 2: N뿯ƽ뿯ẽc m뿯ẽt mu뿯ẽn m뿯½ng','','publish','open','closed','','chuong-2-nuoc-mat-muon-mang','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-2-nuoc-mat-muon-mang/',0,'chuong','',0),(36,3,'2026-10-07 12:08:40','2026-10-07 12:08:40','Anh l뿯½ đ뿯ẽi ca l뿯ẽnh l뿯½ng kh뿯½t ti뿯ẽng khu ch뿯ẽ cũ, ng뿯ƽ뿯ẽi ng뿯ƽ뿯ẽi s뿯ẽ h뿯½i. Nh뿯ƽng m뿯ẽi chi뿯ẽu th뿯ẽ B뿯ẽy, anh đ뿯ẽu ngoan ngo뿯½n ng뿯ẽi tr뿯ƽ뿯ẽc gi뿯½ v뿯ẽ c뿯ẽa c뿯½ gi뿯½o nh뿯ẽ, ng뿯ƽ뿯ẽng ng뿯½ng đ뿯ẽ c뿯½ s뿯ẽa t뿯ẽng n뿯½t c뿯ẽ m뿯½u xanh m뿯ƽ뿯ẽp...','V뿯ẽ Ng뿯ẽt Sau M뿯ƽa: Đ뿯ẽi Ca Giang H뿯ẽ V뿯½ C뿯½ Gi뿯½o D뿯ẽy V뿯ẽ','','publish','open','closed','','vi-ngot-sau-mua-dai-ca-giang-ho-va-co-giao-day-ve','','','2026-10-07 12:08:40','2026-10-07 12:08:40','',0,'https://muopdangcungcovingot.io.vn/truyen/vi-ngot-sau-mua-dai-ca-giang-ho-va-co-giao-day-ve/',0,'truyen','',1),(37,3,'2026-10-07 12:08:41','2026-10-07 12:08:41','<p>L뿯ẽc Phong ng뿯ẽi co ro tr뿯½n chi뿯ẽc gh뿯ẽ g뿯ẽ nh뿯ẽ x뿯½u, hai c뿯½nh tay xăm tr뿯ẽ v뿯ẽng v뿯ẽ c뿯ẽm chi뿯ẽc c뿯ẽ v뿯ẽ m뿯½u n뿯ƽ뿯ẽc.</p><p>Th뿯ẽm Dao m뿯ẽm c뿯ƽ뿯ẽi ti뿯ẽn l뿯ẽi g뿯ẽn, b뿯½n tay m뿯½t r뿯ƽ뿯ẽi ch뿯ẽm v뿯½o mu b뿯½n tay anh: \'Anh Phong th뿯ẽ l뿯ẽng c뿯ẽ tay ra m뿯ẽt ch뿯½t, v뿯ẽ l뿯½ m뿯ƽ뿯ẽp đ뿯ẽng th뿯½ n뿯½t c뿯ẽ ph뿯ẽi m뿯ẽm m뿯ẽi nh뿯ƽ th뿯ẽ n뿯½y n뿯½.\'</p><p>M뿯ẽt ng뿯ƽ뿯ẽi đ뿯½n 뿯½ng cao m뿯½t t뿯½m lăm b뿯ẽng đ뿯ẽ b뿯ẽng nh뿯ƽ g뿯ẽc ch뿯½n.</p>','Ch뿯ƽ뿯ƽng 1: L뿯ẽp h뿯ẽc v뿯ẽ chi뿯ẽu th뿯ẽ B뿯ẽy','','publish','open','closed','','chuong-1-lop-hoc-ve-chieu-thu-bay','','','2026-10-07 12:08:41','2026-10-07 12:08:41','',0,'https://muopdangcungcovingot.io.vn/chuong/chuong-1-lop-hoc-ve-chieu-thu-bay/',0,'chuong','',0),(38,3,'2026-10-07 12:08:41','2026-10-07 12:08:41','<p>C뿯ƽn m뿯ƽa r뿯½o m뿯½a h뿯ẽ b뿯ẽt ng뿯ẽ đ뿯ẽ xu뿯ẽng con ph뿯ẽ nh뿯ẽ.</p><p>L뿯ẽc Phong bung chi뿯ẽc 뿯½ m뿯½u xanh b뿯ƽ to b뿯ẽn che k뿯½n cho Th뿯ẽm Dao, m뿯ẽc cho n뿯ẽa vai m뿯½nh 뿯ƽ뿯ẽt đ뿯ẽm n뿯ƽ뿯ẽc m뿯ƽa: \'Đ뿯ẽ anh đ뿯ƽa em v뿯ẽ, tr뿯ẽi t뿯ẽi r뿯ẽi ngo뿯½i đ뿯ƽ뿯ẽng kh뿯½ng an to뿯½n.\'</p>','Ch뿯ƽ뿯ƽng 2: 